import { encodeSignalBatch } from './codec.js';
 export function flushPendingSignals(pending, sink) {
   if (pending.length === 0) return 0;
   sink.write(encodeSignalBatch(pending));
   return pending.length;
 }
 export function discardPendingSignals(pending) { pending.length = 0; }

