import { test, mock } from 'node:test';
 import assert from 'node:assert/strict';
 import { flushPendingSignals, discardPendingSignals } from '../src/buffer.js';
 test('reconnect emits a single frame', () => {
   const write = mock.fn();
   flushPendingSignals([{ id: 's4' }, { id: 's5' }], { write });
   assert.equal(write.mock.callCount(), 1);
 });
 test('discard clears the queue', () => {
   const queue = [{ id: 's6' }];
   discardPendingSignals(queue);
   assert.equal(queue.length, 0);
 });
